              {"number": 12, "prompt": "Chand Baori (850 AD) — Has _______ which provide a view to the steps.", "answer": ["verandas", "verandahs"], "wordLimit": 1, "explanation": "'On the fourth side, verandas which are supported by ornate pillars overlook the steps.'", "evidence": {"sectionId": "p1", "ref": "K", "quote": "On the fourth side, verandas which are supported by ornate pillars overlook the steps"}},
              {"number": 13, "prompt": "Neemrana Ki Baori (1700) — Has two _______ levels.", "answer": ["underwater"], "wordLimit": 1, "explanation": "Neemrana Ki Baori 'is nine storeys deep, with the last two being underwater'.", "evidence": {"sectionId": "p1", "ref": "L", "quote": "with the last two being underwater"}}
