              {"number": 37, "prompt": "Most people have the potential to be creative.", "answer": "YES", "explanation": "'Almost every individual can be creative in the right circumstances'.", "evidence": {"sectionId": "p3", "ref": "B", "quote": "almost every individual can be creative in the right circumstances"}},
