            "questions": [
              {"number": 1, "prompt": "Paragraph B", "answer": "ii",  "explanation": "Paragraph B describes how mass tourism began in England in the industrial era and expanded via commercial aviation.", "evidence": {"sectionId": "p1", "ref": "B", "quote": "Tourism in the mass form as we know it today is a distinctly twentieth-century phenomenon"}},
              {"number": 2, "prompt": "Paragraph C", "answer": "i",   "explanation": "Paragraph C covers the economic and social importance of tourism, including employment and GDP.", "evidence": {"sectionId": "p1", "ref": "C", "quote": "Tourism today has grown significantly in both economic and social importance"}},
              {"number": 3, "prompt": "Paragraph D", "answer": "v",   "explanation": "Paragraph D explains why diversity and fragmentation make tourism's economic impact hard to measure.", "evidence": {"sectionId": "p1", "ref": "D", "quote": "the major problems of the travel and tourism industry that have hidden, or obscured, its economic impact are the diversity and fragmentation of the industry itself"}},
              {"number": 4, "prompt": "Paragraph E", "answer": "vii", "explanation": "Paragraph E outlines tourism's position as the world's largest industry across many nations.", "evidence": {"sectionId": "p1", "ref": "E", "quote": "tourism has become the largest commodity in international trade for many nations"}}
