            "instructions": "Complete the notes below. Choose ONE WORD ONLY from the passage for each answer.",
            "questions": [
              {"number": 19, "prompt": "The most vividly coloured red leaves are found on the side of the tree facing the _______.", "answer": ["sun"], "wordLimit": 1, "explanation": "'The leaves that are the reddest are those on the side of the tree which gets most sun.'", "evidence": {"sectionId": "p2", "ref": "H", "quote": "the leaves that are the reddest are those on the side of the tree which gets most sun"}},
              {"number": 20, "prompt": "The _______ surfaces of leaves contain the most red pigment.", "answer": ["upper"], "wordLimit": 1, "explanation": "'The red is brighter on the upper side of the leaf.'", "evidence": {"sectionId": "p2", "ref": "H", "quote": "the red is brighter on the upper side of the leaf"}},
              {"number": 21, "prompt": "Red leaves are most abundant when daytime weather conditions are _______ and sunny.", "answer": ["dry"], "wordLimit": 1, "explanation": "'The best conditions for intense red colours are dry, sunny days and cool nights.'", "evidence": {"sectionId": "p2", "ref": "H", "quote": "the best conditions for intense red colours are dry, sunny days and cool nights"}},
              {"number": 22, "prompt": "The intensity of the red colour of leaves increases as you go further _______.", "answer": ["north"], "wordLimit": 1, "explanation": "'Trees such as maples usually get much redder the more north you travel in the northern hemisphere.'", "evidence": {"sectionId": "p2", "ref": "H", "quote": "trees such as maples usually get much redder the more north you travel in the northern hemisphere"}}
            ]
