-- TEST 4  The Megafires of California · Second Nature · When Evolution Runs Backwards
-- ═══════════════════════════════════════════════════════════════
INSERT INTO public.tests (skill, book, test_label, variant, duration_seconds, content, published)
VALUES (
  'reading', 'Cambridge IELTS 10', 'Test 4', 'academic', 3600,
  $json4${
    "skill": "reading",
    "book": "Cambridge IELTS 10",
    "testLabel": "Test 4",
    "variant": "academic",
    "durationSeconds": 3600,
    "sections": [
      {
        "id": "p1",
        "title": "Passage 1",
        "passage": [
          {"ref": "1",  "text": "Wildfires are becoming an increasing menace in the western United States, with Southern California being the hardest hit area. There is a reason fire squads battling more frequent blazes in Southern California are having such difficulty containing the flames, despite better preparedness than ever and decades of experience fighting fires fanned by the Santa Ana Winds. The wildfires themselves, experts say, are generally hotter, faster, and spread more erratically than in the past."},
          {"ref": "2",  "text": "Megafires, also called siege fires, are the increasingly frequent blazes that burn 500,000 acres or more — 10 times the size of the average forest fire of 20 years ago. Some recent wildfires are among the biggest ever in California in terms of acreage burned, according to state figures and news reports."},
          {"ref": "3",  "text": "One explanation for the trend to more superhot fires is that the region, which usually has dry summers, has had significantly below normal precipitation in many recent years. Another reason, experts say, is related to the century-long policy of the US Forest Service to stop wildfires as quickly as possible. The unintentional consequence has been to halt the natural eradication of underbrush, now the primary fuel for megafires."},
          {"ref": "4",  "text": "Three other factors contribute to the trend, they add. First is climate change, marked by a 1-degree Fahrenheit rise in average yearly temperature across the western states. Second is fire seasons that on average are 78 days longer than they were 20 years ago. Third is increased construction of homes in wooded areas."},
          {"ref": "5",  "text": "'We are increasingly building our homes in fire-prone ecosystems,' says Dominik Kulakowski, adjunct professor of biology at Clark University Graduate School of Geography. 'Doing that in many of the forests of the western US is like building homes on the side of an active volcano.'"},
          {"ref": "6",  "text": "In California, where population growth has averaged more than 600,000 a year for at least a decade, more residential housing is being built. 'What once was open space is now residential homes providing fuel to make fires burn with greater intensity,' says Terry McHale of the California Department of Forestry firefighters' union. 'With so much dryness, so many communities to catch fire, so many fronts to fight, it becomes an almost incredible job.'"},
          {"ref": "7",  "text": "That said, many experts give California high marks for making progress on preparedness in recent years, after some of the largest fires in state history scorched thousands of acres, burned thousands of homes, and killed numerous people. Stung in the past by criticism of bungling that allowed fires to spread when they might have been contained, personnel are meeting the peculiar challenges of neighbourhood- and canyon-hopping fires better than previously, observers say."},
          {"ref": "8",  "text": "State promises to provide more up-to-date engines, planes, and helicopters to fight fires have been fulfilled. Firefighters' unions that in the past complained of dilapidated equipment, old fire engines, and insufficient blueprints for fire safety are now praising the state's commitment, noting that funding for firefighting has increased, despite huge cuts in many other programs."},
          {"ref": "9",  "text": "Besides providing money to upgrade the fire engines that must traverse the mammoth state and wind along serpentine canyon roads, the state has invested in better command-and-control facilities as well as in the strategies to run them. 'In the fire sieges of earlier years, we found that other jurisdictions and states were willing to offer mutual-aid help, but we were not able to communicate adequately with them,' says Kim Zagaris, chief of the state's Office of Emergency Services Fire and Rescue Branch."},
          {"ref": "10", "text": "After a commission examined and revamped communications procedures, the statewide response has become far more professional and responsive. There is a sense among both government officials and residents that the speed, dedication, and coordination of firefighters from several states and jurisdictions are resulting in greater efficiency than in past siege fire situations."},
          {"ref": "11", "text": "In recent years, the Southern California region has improved building codes, evacuation procedures, and procurement of new technology. 'I am extraordinarily impressed by the improvements we have witnessed,' says Randy Jacobs, a Southern California-based lawyer who has had to evacuate both his home and business to escape wildfires. 'Notwithstanding all the damage that will continue to be caused by wildfires, we will no longer suffer the loss of life endured in the past because of the fire prevention and firefighting measures that have been put in place,' he says."}
        ],
        "groups": [
          {
            "type": "short_answer",
            "instructions": "Complete the notes below. Choose ONE WORD AND/OR A NUMBER from the passage for each answer.",
            "questions": [
              {"number": 1, "prompt": "Movement of wildfires: _______ more unpredictably", "answer": ["spread"], "wordLimit": 2, "explanation": "'The wildfires themselves are generally hotter, faster, and spread more erratically than in the past.'", "evidence": {"sectionId": "p1", "ref": "1", "quote": "spread more erratically than in the past"}},
              {"number": 2, "prompt": "Size of fires: _______ greater on average than two decades ago", "answer": ["10 times", "ten times"], "wordLimit": 2, "explanation": "Megafires are '10 times the size of the average forest fire of 20 years ago'.", "evidence": {"sectionId": "p1", "ref": "2", "quote": "10 times the size of the average forest fire of 20 years ago"}},
              {"number": 3, "prompt": "Rainfall: _______ average", "answer": ["below"], "wordLimit": 2, "explanation": "'The region has had significantly below normal precipitation in many recent years.'", "evidence": {"sectionId": "p1", "ref": "3", "quote": "has had significantly below normal precipitation in many recent years"}},
              {"number": 4, "prompt": "More brush available to act as _______", "answer": ["fuel"], "wordLimit": 2, "explanation": "Halting natural eradication of underbrush left it as 'the primary fuel for megafires'.", "evidence": {"sectionId": "p1", "ref": "3", "quote": "halt the natural eradication of underbrush, now the primary fuel for megafires"}},
              {"number": 5, "prompt": "Extended fire _______", "answer": ["seasons"], "wordLimit": 2, "explanation": "'Fire seasons that on average are 78 days longer than they were 20 years ago.'", "evidence": {"sectionId": "p1", "ref": "4", "quote": "fire seasons that on average are 78 days longer than they were 20 years ago"}},
              {"number": 6, "prompt": "More building of _______ in vulnerable places", "answer": ["homes", "housing"], "wordLimit": 2, "explanation": "'Increased construction of homes in wooded areas.'", "evidence": {"sectionId": "p1", "ref": "4", "quote": "Third is increased construction of homes in wooded areas"}}
            ]
          },
          {
            "type": "true_false_notgiven",
            "instructions": "Do the following statements agree with the information given in Reading Passage 1? Write TRUE, FALSE, or NOT GIVEN.",
            "questions": [
              {"number": 7,  "prompt": "The amount of open space in California has diminished over the last ten years.", "answer": "TRUE", "explanation": "'What once was open space is now residential homes' — open space has diminished.", "evidence": {"sectionId": "p1", "ref": "6", "quote": "What once was open space is now residential homes providing fuel to make fires burn with greater intensity"}},
              {"number": 8,  "prompt": "Many experts believe California has made little progress in readying itself to fight fires.", "answer": "FALSE", "explanation": "'Many experts give California high marks for making progress on preparedness' — the opposite of little progress.", "evidence": {"sectionId": "p1", "ref": "7", "quote": "many experts give California high marks for making progress on preparedness in recent years"}},
              {"number": 9,  "prompt": "Personnel in the past have been criticised for mishandling fire containment.", "answer": "TRUE", "explanation": "'Stung in the past by criticism of bungling that allowed fires to spread when they might have been contained.'", "evidence": {"sectionId": "p1", "ref": "7", "quote": "Stung in the past by criticism of bungling that allowed fires to spread when they might have been contained"}},
              {"number": 10, "prompt": "California has replaced a range of firefighting tools.", "answer": "TRUE", "explanation": "'State promises to provide more up-to-date engines, planes, and helicopters to fight fires have been fulfilled.'", "evidence": {"sectionId": "p1", "ref": "8", "quote": "State promises to provide more up-to-date engines, planes, and helicopters to fight fires have been fulfilled"}},
              {"number": 11, "prompt": "More firefighters have been hired to improve fire-fighting capacity.", "answer": "NOT GIVEN", "explanation": "The passage discusses funding and equipment upgrades but gives no information about hiring more firefighters.", "evidence": {"sectionId": "p1", "ref": "8", "quote": "funding for firefighting has increased, despite huge cuts in many other programs"}},
              {"number": 12, "prompt": "Citizens and government groups disapprove of the efforts of different states and agencies working together.", "answer": "FALSE", "explanation": "'There is a sense among both government officials and residents that... coordination... are resulting in greater efficiency' — they approve.", "evidence": {"sectionId": "p1", "ref": "10", "quote": "There is a sense among both government officials and residents that the speed, dedication, and coordination of firefighters from several states and jurisdictions are resulting in greater efficiency"}},
              {"number": 13, "prompt": "Randy Jacobs believes that loss of life from fires will continue at the same levels, despite changes made.", "answer": "FALSE", "explanation": "Jacobs says 'we will no longer suffer the loss of life endured in the past' — he expects fewer deaths.", "evidence": {"sectionId": "p1", "ref": "11", "quote": "we will no longer suffer the loss of life endured in the past because of the fire prevention and firefighting measures that have been put in place"}}
            ]
          }
        ]
      },
      {
        "id": "p2",
        "title": "Passage 2",
        "passage": [
          {"ref": "A", "text": "Psychologists have long held that a person's character cannot undergo a transformation in any meaningful way and that the key traits of personality are determined at a very young age. However, researchers have begun looking more closely at ways we can change. Positive psychologists have identified 24 qualities we admire, such as loyalty and kindness, and are studying them to find out why they come so naturally to some people. What they are discovering is that many of these qualities amount to habitual behaviour that determines the way we respond to the world. The good news is that all this can be learned. Some qualities are less challenging to develop than others, optimism being one of them. However, developing qualities requires mastering a range of skills which are diverse and sometimes surprising. For example, to bring more joy and passion into your life, you must be open to experiencing negative emotions. Cultivating such qualities will help you realise your full potential."},
          {"ref": "B", "text": "'The evidence is good that most personality traits can be altered,' says Christopher Peterson, professor of psychology at the University of Michigan, who cites himself as an example. Inherently introverted, he realised early on that as an academic, his reticence would prove disastrous in the lecture hall. So he learned to be more outgoing and to entertain his classes. 'Now my extroverted behaviour is spontaneous,' he says."},
          {"ref": "C", "text": "David Fajgenbaum had to make a similar transition. He was preparing for university, when he had an accident that put an end to his sports career. On campus, he quickly found that beyond ordinary counselling, the university had no services for students who were undergoing physical rehabilitation and suffering from depression like him. He therefore launched a support group to help others in similar situations. He took action despite his own pain — a typical response of an optimist."},
          {"ref": "D", "text": "Suzanne Segerstrom, professor of psychology at the University of Kentucky, believes that the key to increasing optimism is through cultivating optimistic behaviour, rather than positive thinking. She recommends you train yourself to pay attention to good fortune by writing down three positive things that come about each day. This will help you convince yourself that favourable outcomes actually happen all the time, making it easier to begin taking action."},
          {"ref": "E", "text": "You can recognise a person who is passionate about a pursuit by the way they are so strongly involved in it. Tanya Streeter's passion is freediving — the sport of plunging deep into the water without tanks or other breathing equipment. Beginning in 1998, she set nine world records and can hold her breath for six minutes. The physical stamina required for this sport is intense but the psychological demands are even more overwhelming. Streeter learned to untangle her fears from her judgment of what her body and mind could do. 'In my career as a competitive freediver, there was a limit to what I could do — but it was not anywhere near what I thought it was,' she says."},
          {"ref": "F", "text": "Finding a pursuit that excites you can improve anyone's life. The secret about consuming passions, though, according to psychologist Paul Silvia of the University of North Carolina, is that they require discipline, hard work and ability, which is why they are so rewarding. Psychologist Todd Kashdan has this advice for those people taking up a new passion: 'As a newcomer, you also have to tolerate and laugh at your own ignorance. You must be willing to accept the negative feelings that come your way,' he says."},
          {"ref": "G", "text": "In 2004, physician-scientist Mauro Zappaterra began his PhD research at Harvard Medical School. Unfortunately, he was miserable as his research was not compatible with his curiosity about healing. He finally took a break and during eight months in Santa Fe, Zappaterra learned about alternative healing techniques not taught at Harvard. When he got back, he switched labs to study how cerebrospinal fluid nourishes the developing nervous system. He also vowed to look for the joy in everything, including failure, as this could help him learn about his research and himself."},
          {"ref": "H", "text": "Usually, we think of courage in physical terms but ordinary life demands something else. For marketing executive Kenneth Pedeleose, it meant speaking out against something he thought was ethically wrong. The new manager was intimidating staff so Pedeleose carefully recorded each instance of bullying and eventually took the evidence to a senior director, knowing his own job security would be threatened. Eventually the manager was the one to go. According to Cynthia Pury, a psychologist at Clemson University, Pedeleose's story proves the point that courage is not motivated by fearlessness, but by moral obligation. Pury also believes that people can acquire courage. Many of her students said that faced with a risky situation, they first tried to calm themselves down, then looked for a way to mitigate the danger, just as Pedeleose did by documenting his allegations."}
        ],
